package com.coders.patterns;
public class solidRectangle {

	public static void main(String[] args) {
		// TODO Auto-generated method stub4
        for (int i = 1; i <= 5; i++) {

            for (int j = 1; j <= 5; j++) {
                System.out.print("* ");
            }

            System.out.println();
		}	
	}

}
